 code(id+"_collect","Keep validated part",`const {items:ignored,...p}=nodes.${id}_task,t=p.tasks[p.index]; return [{...p,values:[...p.values,{key:t.key,index:t.index,lines:item.json.lines}],index:p.index+1}];`);
